const method = $input.first().json.headers?.['x-forwarded-method'] || $input.first().json.method || '';
if (method === 'OPTIONS') {
  $execution.respond({
    statusCode: 200,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-App-Token'
    },
    body: ''
  });
  return [];
}
return $input.all();

const body = $input.first().json.body || $input.first().json;
const base64Data = body.file_base64 || body.base64 || body.data || '';
const fileName = body.file_name || body.fileName || `signature_${Date.now()}.jpg`;
const folderId = body.folder_id || body.folderId || '';

if (!base64Data) {
  return [{ json: { ok: false, error: 'No file data provided' } }];
}

// Remove data URL prefix if present
let cleanBase64 = base64Data;
let mimeType = 'image/jpeg';
if (base64Data.startsWith('data:')) {
  const matches = base64Data.match(/^data:([^;]+);base64,(.+)$/);
  if (matches) {
    mimeType = matches[1];
    cleanBase64 = matches[2];
  }
}

// Convert base64 to binary buffer
const buffer = Buffer.from(cleanBase64, 'base64');

return [{
  json: {
    ok: true,
    file_name: fileName,
    mime_type: mimeType,
    folder_id: folderId,
    file_size: buffer.length,
    _buffer: buffer.toString('base64')
  }
}];

const uploadResult = $input.first().json;
const fileId = uploadResult.id || '';
const fileName = uploadResult.name || '';

if (!fileId) {
  return [{ json: { ok: false, error: 'Upload failed - no file ID returned' } }];
}

// Build Google Drive view URL
const driveUrl = `https://drive.google.com/uc?export=view&id=${fileId}`;

return [{
  json: {
    ok: true,
    file_id: fileId,
    file_name: fileName,
    drive_url: driveUrl,
    message: 'File uploaded successfully'
  }
}];
